            state["phase"] = "UNLOCK"
            state["t"] = 0

    elif state["phase"] == "UNLOCK":
        # Apply backward force to unlock
        fx_cmd = BACKWARD_FX_THRESHOLD - 1.0  # Ensure strictly < -34.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        # Ensure speed is below maximum
        if math.hypot(vx_p, vy_p) >= BACKWARD_SPEED_MAX:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"

    elif state["phase"] == "ESCAPE":
        fx = 15.0
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

    # Apply forces with bounds
    fx = max(min(fx, MAX_FORCE), MIN_FORCE)
    fy = max(min(fy, MAX_FORCE), MIN_FORCE)
    sandbox.apply_agent_force(fx, fy)
    MEM.data["initial_state"] = state

import math

ACTIVATION_X_MIN = 5.0
ACTIVATION_X_MAX = 10.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0
MAX_FORCE = 200.0
MIN_FORCE = -200.0
WALL_DISTANCE_THRESHOLD = 0.3  # meters
FORWARD_FORCE = 25.0  # Increased to push through environmental resistance
LATERAL_FORCE = 15.0  # Force to move away from walls
VELOCITY_TOLERANCE = 0.5
SHRINKING_FORCE = 1.0  # Gradually reduce force when approaching the wall

def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }

class Memory:
    def __init__(self):
        self.data = {}

    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    state = MEM.data.get("initial_state", {
        "phase": "APPROACH",
        "t": 0,
        "lx": None,
        "ly": None,
        "vx": 0.0,
        "vy": 0.0,
    })

    pd = sandbox.get_agent_position()
    vx_p, vy_p = sandbox.get_agent_velocity()
    x, y = pd
    front, up, down = sandbox.get_whisker_readings()
    ty = 1.5
    w_comp = _weight_comp(sandbox)

    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }

    if state["phase"] == "APPROACH":
        # Navigate using whiskers to avoid walls
        if front < WALL_DISTANCE_THRESHOLD:
            # Apply lateral force to move away from the wall
            # Assume wall is in front, move left (negative x) to navigate around
            fx = -LATERAL_FORCE
            fy = 0.0  # No vertical force when near the wall
        else:
            # Move forward toward the activation zone
            if x < ACTIVATION_X_MIN:
                fx = FORWARD_FORCE
            else:
                fx = 10.0 * (ACTIVATION_X_MAX - x) - 5.0 * vx_p
            fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        # Check if in activation zone
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(vx_p) < VELOCITY_TOLERANCE:
            state["phase"] = "UNLOCK"
            state["t"] = 0

    elif state["phase"] == "UNLOCK":
        # Apply backward force to unlock
        fx_cmd = BACKWARD_FX_THRESHOLD - 1.0  # Ensure strictly < -34.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        # Ensure speed is below maximum
        if math.hypot(vx_p, vy_p) >= BACKWARD_SPEED_MAX:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"

    elif state["phase"] == "ESCAPE":
        fx = 15.0
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

    # Apply forces with bounds
    fx = max(min(fx, MAX_FORCE), MIN_FORCE)
    fy = max(min(fy, MAX_FORCE), MIN_FORCE)
    sandbox.apply_agent_force(fx, fy)
    MEM.data["initial_state"] = state
